package com.autoleuy;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("autoleuy")
public interface AutoLeuyConfig extends Config
{
	@ConfigItem(
		keyName = "greeting",
		name = "Welcome Greeting",
		description = "The message to show to the user when they login"
	)
	default String greeting()
	{
		return "Hello";
	}
}

package com.autoleuy;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class AutoLeuyOverlay extends OverlayPanel
{
    private final AutoLeuyPlugin plugin;

    @Inject
    AutoLeuyOverlay(AutoLeuyPlugin plugin)
    {
        super(plugin);
        this.plugin = plugin;

        setPosition(OverlayPosition.TOP_LEFT);

        addMenuEntry(
                MenuAction.RUNELITE_OVERLAY,
                "Reset run",
                "Auto Leuy",
                entry -> plugin.resetRun()
        );
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text("Auto Leuy - PK Run")
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Held Keys:")
                        .right(String.valueOf(plugin.getHeldKeyCount()))
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Run Keys:")
                        .right(String.valueOf(plugin.getRunKeyCount()))
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Run Value:")
                        .right(String.format("%,d gp", plugin.getRunValue()))
                        .build()
        );

        return super.render(graphics);
    }
}

package com.autoleuy;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Auto Luey",
		description = "Tracks Wilderness loot keys and their value during PK runs"
)
@Slf4j
public class AutoLeuyPlugin extends Plugin
{
	/*
	 * Wilderness loot keys currently use five item IDs:
	 * 26651 through 26655.
	 */
	private static final int LOOT_KEY_MIN_ID = 26651;
	private static final int LOOT_KEY_MAX_ID = 26655;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AutoLeuyOverlay overlay;

	private int heldKeyCount = 0;
	private int runKeyCount = 0;
	private long runValue = 0;

	private boolean inventoryInitialized = false;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		if (event.getMessage().toLowerCase().contains("loot key"))
		{
			log.debug(
					"LOOT KEY MESSAGE: '{}' | pendingKey={} | valuedKeys={}",
					event.getMessage(),
					pendingCheckedKeyId,
					valuedKeyIds
			);
		}

		Matcher matcher = LOOT_KEY_VALUE_PATTERN.matcher(event.getMessage());

		if (!matcher.find())
		{
			return;
		}

		/*
		 * Only accept this value if we know the player just
		 * clicked "Check" on an actual Wilderness loot key.
		 */
		if (
				pendingCheckedKeyId < LOOT_KEY_MIN_ID ||
						pendingCheckedKeyId > LOOT_KEY_MAX_ID
		)
		{
			return;
		}

		long keyValue = Long.parseLong(
				matcher.group(1).replace(",", "")
		);

		/*
		 * Only count this particular key once.
		 */
		if (valuedKeyIds.add(pendingCheckedKeyId))
		{
			runValue += keyValue;

			log.debug(
					"Auto Leuy valued loot key {} at {} gp. Run value: {}",
					pendingCheckedKeyId,
					keyValue,
					runValue
			);
		}
		else
		{
			log.debug(
					"Auto Leuy ignored repeat check of loot key {}",
					pendingCheckedKeyId
			);
		}

		pendingCheckedKeyId = -1;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!event.getMenuOption().equalsIgnoreCase("Check"))
		{
			return;
		}

		int itemId = event.getItemId();

		if (
				itemId >= LOOT_KEY_MIN_ID &&
						itemId <= LOOT_KEY_MAX_ID
		)
		{
			pendingCheckedKeyId = itemId;

			log.debug("Auto Leuy is checking loot key {}", itemId);
		}
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);

		clientThread.invokeLater(() ->
		{
			ItemContainer inventory = client.getItemContainer(InventoryID.INV);

			if (inventory != null)
			{
				heldKeyCount = countLootKeys(inventory);
				inventoryInitialized = true;
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		// Ignore banks, equipment, loot interfaces, etc.
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		Set<Integer> currentlyHeldKeyIds =
				getHeldLootKeyIds(event.getItemContainer());

		log.debug(
				"Inventory key change | held={} | valued before={}",
				currentlyHeldKeyIds,
				valuedKeyIds
		);

		/*
		 * Forget duplicate-check state for any loot key that has
		 * left the inventory.
		 *
		 * This allows the game to reuse that loot-key item ID for
		 * a newly earned key later in the same PK run.
		 */
		valuedKeyIds.retainAll(currentlyHeldKeyIds);

		log.debug(
				"Valued keys after cleanup={}",
				valuedKeyIds
		);

		/*
		 * If a key left the inventory while we were waiting for
		 * its Check response, cancel that pending check.
		 */
		if (
				pendingCheckedKeyId != -1 &&
						!currentlyHeldKeyIds.contains(pendingCheckedKeyId)
		)
		{
			pendingCheckedKeyId = -1;
		}

		int newHeldKeyCount = countLootKeys(event.getItemContainer());

		/*
		 * If this is our first inventory update, establish the
		 * baseline instead of recording existing keys as new.
		 */
		if (!inventoryInitialized)
		{
			heldKeyCount = newHeldKeyCount;
			inventoryInitialized = true;
			return;
		}

		/*
		 * If the number of held keys increased, we received
		 * one or more new loot keys.
		 */
		if (newHeldKeyCount > heldKeyCount)
		{
			int keysGained = newHeldKeyCount - heldKeyCount;

			runKeyCount += keysGained;

			log.debug(
					"Auto Leuy detected {} new loot key(s). Run total: {}",
					keysGained,
					runKeyCount
			);
		}

		heldKeyCount = newHeldKeyCount;
	}

	private int countLootKeys(ItemContainer inventory)
	{
		int count = 0;

		for (Item item : inventory.getItems())
		{
			int itemId = item.getId();

			if (
					itemId >= LOOT_KEY_MIN_ID &&
							itemId <= LOOT_KEY_MAX_ID
			)
			{
				count++;
			}
		}

		return count;
	}

	private static final Pattern LOOT_KEY_VALUE_PATTERN = Pattern.compile(
			"Your loot key contains items that are worth (?:approximately )?([\\d,]+)\\s*gp\\.?",
			Pattern.CASE_INSENSITIVE
	);

	/*
	 * Loot-key item IDs whose value has already been counted.
	 * This stops repeated "Check" clicks from inflating the run.
	 */
	private final Set<Integer> valuedKeyIds = new HashSet<>();

	/*
	 * The loot key most recently clicked with "Check".
	 */
	private int pendingCheckedKeyId = -1;

	void resetRun()
	{
		runKeyCount = 0;
		runValue = 0;
		valuedKeyIds.clear();
		pendingCheckedKeyId = -1;
	}

	private Set<Integer> getHeldLootKeyIds(ItemContainer inventory)
	{
		Set<Integer> heldIds = new HashSet<>();

		for (Item item : inventory.getItems())
		{
			int itemId = item.getId();

			if (
					itemId >= LOOT_KEY_MIN_ID &&
							itemId <= LOOT_KEY_MAX_ID
			)
			{
				heldIds.add(itemId);
			}
		}

		return heldIds;
	}

	int getHeldKeyCount()
	{
		return heldKeyCount;
	}

	int getRunKeyCount()
	{
		return runKeyCount;
	}

	long getRunValue()
	{
		return runValue;
	}
}

package com.autoleuy;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AutoLeuyPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AutoLeuyPlugin.class);
		RuneLite.main(args);
	}
}
